/* rhu_pal_messageheader: the runtime's MessageHeader, field for field; offsets and size at the 32-bit
 * ARM EABI asserted below. */
typedef struct rhu_pal_messageheader {
    uint8_t *SocketAddress;
    struct rhu_pal_iovector *IOVectors;
    uint8_t *ControlBuffer;
    int32_t SocketAddressLen;
    int32_t IOVectorCount;
    int32_t ControlBufferLen;
    int32_t Flags;
} rhu_pal_messageheader;
_Static_assert(sizeof(rhu_pal_messageheader) == 28, "rhu_pal_messageheader size");
_Static_assert(offsetof(rhu_pal_messageheader, SocketAddress) == 0, "rhu_pal_messageheader.SocketAddress offset");
_Static_assert(offsetof(rhu_pal_messageheader, IOVectors) == 4, "rhu_pal_messageheader.IOVectors offset");
_Static_assert(offsetof(rhu_pal_messageheader, ControlBuffer) == 8, "rhu_pal_messageheader.ControlBuffer offset");
_Static_assert(offsetof(rhu_pal_messageheader, SocketAddressLen) == 12, "rhu_pal_messageheader.SocketAddressLen offset");
_Static_assert(offsetof(rhu_pal_messageheader, IOVectorCount) == 16, "rhu_pal_messageheader.IOVectorCount offset");
_Static_assert(offsetof(rhu_pal_messageheader, ControlBufferLen) == 20, "rhu_pal_messageheader.ControlBufferLen offset");
_Static_assert(offsetof(rhu_pal_messageheader, Flags) == 24, "rhu_pal_messageheader.Flags offset");

